package android.content;
public class Intent {private android.net.Uri data;public Intent setData(android.net.Uri value){data=value;return this;}public android.net.Uri getData(){return data;}private ComponentName component;public static final String ACTION_PACKAGE_REPLACED="android.intent.action.PACKAGE_REPLACED",ACTION_PACKAGE_REMOVED="android.intent.action.PACKAGE_REMOVED",ACTION_PACKAGE_CHANGED="android.intent.action.PACKAGE_CHANGED",ACTION_USER_UNLOCKED="android.intent.action.USER_UNLOCKED",EXTRA_USER_HANDLE="android.intent.extra.user_handle";private String action;private int user=-10000;public Intent(){}public Intent(String a){action=a;}public String getAction(){return action;}public Intent putExtra(String key,int value){if(!EXTRA_USER_HANDLE.equals(key))throw new AssertionError("known extra");user=value;return this;}public int getIntExtra(String key,int fallback){return EXTRA_USER_HANDLE.equals(key)?user:fallback;}public Intent setComponent(ComponentName c){component=c;return this;}public ComponentName getComponent(){return component;}}
